legacyCss:
.h1-1 {margin:0;padding:0;}
@font-face { font-family: 'Nirmala UI Semilight'; src:url(/"/fonts/NirmalaS.ttf");}
.fontfamily_C1 { font-family: 'Nirmala UI Semilight';}
#cerfitication-container { background:#002D49;}
#about-top-title { background:#0086CF;}
#cf_map { position:relative;}
#cf_Americas { position:absolute; display:inline-block; color:#FFF; font-weight:bold; top:40%; left:5%;}
#cf_Africa { position:absolute; display:inline-block; color:#FFF; font-weight:bold; top:70%; left:46%;}
#cf_Europe { position:absolute; display:inline-block; color:#FFF; font-weight:bold; top:35%; left:52%;}
#cf_Asia { position:absolute; display:inline-block; color:#FFF; font-weight:bold; top:35%; right:20%;}
#cf_Oceania { position:absolute; display:inline-block; color:#FFF; font-weight:bold; bottom:16%; right:5%;}
.cf_link_area { width:100%; min-height:500px; background:url(/images/CERTIFICATION/img_bg.jpg) no-repeat top center; background-size: cover;}
.cf_link_icon_txt { text-align:center; font-size:13px; color:#FFF; padding-top:10px; padding-bottom:20px; min-height:60px;}
.cf_link a { color:#FFF; font-size:18px; text-decoration:none;}
.cf_link a:hover { color:#CCC; text-decoration:none;}
.cf_txt { font-size:20px;}
.cf_class_bg { background:url(/images/CERTIFICATION/cf_line.png) center no-repeat; margin:20px 10px 30px 10px;}
.cf_class_txt { font-size:46px; font-weight:bold; padding:10px 20px; color:#FFF; display:inline-block; background:#002D49; margin:0;}
.cf_area_c {}
.cf_name { color:#0086CF; font-size:25px; font-weight:bold; padding:20px 0; margin:0;}
.cf_content { color:#FFF; text-align:justify; font-size:18px;}
.pd-btn-info-link { text-align:right; margin:40px 0 40px 0;}
.btn-link { color: #008ecf; border-color:#008ecf; border:1px sloid #008ecf; font-size:18px; padding:10px 20px; border-radius: 30px; min-width:200px;}
.btn-link:focus, .btn-link.focus { color: #333; background-color: #e6e6e6; border-color: #8c8c8c;}
.btn-link:hover { color: #333; background-color: #e6e6e6; border-color: #adadad; text-decoration:none;}
.cf_img { margin-left:10px; margin-right:10px; padding:10px; background:#FFF;}
@media (max-width: 640px) { #cf_Europe { position:absolute; display:inline-block; color:#FFF; font-weight:bold; top:25%; left:52%;}
#cf_Asia { position:absolute; display:inline-block; color:#FFF; font-weight:bold; top:40%; right:20%;}
}
